INSERT INTO public.products (id, name_en, name_bn, category, audience, description_en, description_bn, fabric, origin, badge, image_url)
VALUES
  ('prod-07', 'Deep Plum Off-Shoulder Velvet Evening Gown', 'ডিপ প্লাম অফ-শোল্ডার ভেলভেট ইভনিং গাউন', 'Evening Gowns', 'women', 'Sculpted off-shoulder evening gown crafted in rich plum stretch velvet with pleated bodice detailing.', 'গাঢ় প্লাম স্ট্রেচ ভেলভেটে তৈরি অফ-শোল্ডার ইভনিং গাউন, রিসেপশন ও সন্ধ্যার পার্টির জন্য।', 'Sculpted Stretch Velvet', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1566174053879-31528523f8ae?auto=format&fit=crop&w=900&q=85'),
  ('prod-08', 'Crimson Flowing Satin Reception Gown', 'ক্রিমসন ফ্লোয়িং সাটিন রিসেপশন গাউন', 'Evening Gowns', 'women', 'Full-skirt crimson satin evening gown cut with a clean fitted bodice and sweeping flare for grand receptions.', 'গাঢ় লাল সাটিনে তৈরি ফ্লোয়িং রিসেপশন গাউন, বিবাহোত্তর সংবর্ধনা ও উৎসবের সন্ধ্যার জন্য।', 'Heavy Silk Satin', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=900&q=85'),
  ('prod-09', 'Midnight Navy Jacquard Festive Panjabi', 'মিডনাইট নেভি জ্যাকার্ড ফেস্টিভ পাঞ্জাবি', 'Panjabis', 'men', 'A tailored panjabi in deep navy tonal jacquard, finished with a crisp band collar and covered placket buttons.', 'গভীর নেভি জ্যাকার্ড কাপড়ে নিখুঁত ব্যান্ড কলার ও ম্যাচিং বোতামের উৎসবের পাঞ্জাবি।', 'Woven Cotton Jacquard', 'Dhaka, Bangladesh', 'New Arrival', './products/panjabi-navy-jacquard.jpg'),
  ('prod-10', 'Heritage Tailored Cotton-Silk Dress Shirt', 'হেরিটেজ টেইলর্ড কটন-সিল্ক শার্ট', 'Tailored Shirts', 'men', 'Crisp tailored long-sleeve shirt in fine breathable weave with mother-of-pearl buttons, offered in Slate, Ivory, and Burgundy.', 'স্লেট ব্লু, আইভরি ও বার্গান্ডি রঙে সূক্ষ্ম কটন-সিল্কের নিখুঁত ফরমাল ও সেমি-ফরমাল শার্ট।', 'Long-Staple Cotton-Silk Twill', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=900&q=85'),
  ('prod-11', 'Crimson & Gold Woven Silk Saree', 'ক্রিমসন ও সোনালী বুনন সিল্ক শাড়ি', 'Sarees', 'women', 'Traditional crimson and antique-gold woven buti silk saree paired with a vibrant magenta contrast puff-sleeve blouse.', 'সোনালী বুটি ও জরির পাড়যুক্ত ঐতিহ্যবাহী লাল সিল্ক শাড়ি, ম্যাজেন্টা পাফ-স্লিভ ব্লাউজসহ।', 'Katan Silk with Gold Zari Border', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=900&q=85'),
  ('prod-12', 'Ivory Embroidered Festive Kameez & Emerald Dupatta', 'আইভরি এমব্রয়ডার্ড কামিজ ও পান্না সবুজ ওড়না', 'Salwar Kameez', 'women', 'Printed geometric and floral cotton-silk kameez accented with a solid emerald green chiffon dupatta.', 'রঙিন জ্যামিতিক ও ফ্লোরাল নকশার আইভরি কামিজ, সাথে উজ্জ্বল পান্না সবুজ শিফন ওড়না।', 'Cotton-Silk with Chiffon Dupatta', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1597983073493-88cd35cf93b0?auto=format&fit=crop&w=900&q=85'),
  ('prod-13', 'Royal Navy Tailored Formal Blazer Suit', 'রয়্যাল নেভি টেইলর্ড ফরমাল ব্লেজার স্যুট', 'Blazers & Suits', 'men', 'Two-piece slim tailored royal navy suit with peak lapels, crisp cotton shirting, and burgundy pocket square styling.', 'নিখুঁত কাটিংয়ের রয়্যাল নেভি ফরমাল ব্লেজার স্যুট, বিবাহোত্তর অনুষ্ঠান ও কর্পোরেট ইভেন্টের জন্য।', 'Super 120s Wool Blend', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1617137984095-74e4e5e3613f?auto=format&fit=crop&w=900&q=85'),
  ('prod-14', 'Obsidian Satin-Lapel Double-Breasted Tuxedo', 'অবসিডিয়ান সাটিন-ল্যাপেল ডাবল-ব্রেস্টেড টাক্সিডো', 'Blazers & Suits', 'men', 'Sharp double-breasted black evening tuxedo finished with wide silk-satin peak lapels and covered formal buttons.', 'প্রশস্ত সাটিন ল্যাপেল ও ডাবল-ব্রেস্টেড কাটিংয়ে তৈরি কালো ইভনিং টাক্সিডো।', 'Wool Gabardine with Silk Satin Lapels', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1711385533096-83bd6d587530?auto=format&fit=crop&w=900&q=85'),
  ('prod-15', 'Slate Wool Waistcoat & Navy Shirt Set', 'স্লেট উল ওয়েস্টকোট ও নেভি শার্ট সেট', 'Waistcoats', 'men', 'Textured heather-slate waistcoat tailored for clean layering over a deep navy formal shirt.', 'ডিপ নেভি শার্টের ওপর পরার উপযোগী নিখুঁত ফিটিংয়ের স্লেট গ্রে উল ওয়েস্টকোট।', 'Brushed Wool-Blend Vest & Cotton Poplin Shirt', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1576533247967-79124db83e48?auto=format&fit=crop&w=900&q=85'),
  ('prod-16', 'Midnight Charcoal Two-Piece Tailored Suit', 'মিডনাইট চারকোল টু-পিস টেইলর্ড স্যুট', 'Blazers & Suits', 'men', 'Classic midnight charcoal wool-blend notch-lapel suit cut for wedding receptions and formal dinners.', 'ওয়েডিং রিসেপশন ও ফরমাল ডিনারের জন্য মিডনাইট চারকোল টু-পিস টেইলর্ড স্যুট।', 'Fine Worsted Wool Blend', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=900&q=85'),
  ('prod-17', 'Little Gentleman Navy Cardigan & Bow-Tie Set', 'লিটল জেন্টলম্যান নেভি কার্ডিগান ও বো-টাই সেট', 'Kids Wear', 'kids', 'Soft knit navy cardigan trimmed with sky-blue piping over a crisp white collar shirt, black bow tie, and tailored shorts.', 'সাদা কলার শার্ট, কালো বো-টাই ও স্কাই-ব্লু বর্ডারসহ নরম নেভি নিট কার্ডিগান সেট।', 'Combed Cotton Knit & Crisp Poplin', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1519238263530-99bdd11df2ea?auto=format&fit=crop&w=900&q=85'),
  ('prod-18', 'Little Princess Block-Dot Cotton Festive Top', 'লিটল প্রিন্সেস ব্লক-ডট কটন ফেস্টিভ টপ', 'Kids Wear', 'kids', 'Breathable ivory cotton gathered peasant top patterned with artisanal charcoal block-printed dots.', 'হাতে ব্লক-প্রিন্ট করা কোমল আইভরি সুতি টপ, দিনের বেলার পারিবারিক অনুষ্ঠানের জন্য।', '100% Soft Handloom Cotton', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1518831959646-742c3a14ebf7?auto=format&fit=crop&w=900&q=85'),
  ('prod-19', 'Alabaster Scallop Off-Shoulder Midi Dress', 'অ্যালাবাস্টার স্ক্যালপ অফ-শোল্ডার মিডি ড্রেস', 'Dresses', 'women', 'Breezy alabaster cotton dress with embroidered scalloped ruffle neckline and tiered hem for daytime gatherings.', 'এমব্রয়ডার্ড স্ক্যালপ রাফল নেকলাইন ও আরামদায়ক সুতি কাপড়ের সাদা মিডি ড্রেস।', '100% Embroidered Cotton Eyelet', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=900&q=85'),
  ('prod-20', 'Oatmeal Cable-Knit & Rust Wool Winter Capsule', 'ওটমিল কেবল-নিট ও রাস্ট উল উইন্টার ক্যাপসুল', 'Shawls', 'unisex', 'Curated winter layering piece pairing heavy oatmeal cable-knit textures with warm rust wool-blend drape.', 'ওটমিল কেবল-নিট ও উষ্ণ রাস্ট উল-ব্লেন্ডের শীতকালীন আরামদায়ক লেয়ারিং পোশাক।', 'Brushed Wool & Textured Cotton Knit', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1558769132-cb1aea458c5e?auto=format&fit=crop&w=900&q=85')
